    "fullDescription": "Польовий агрегат ZIBO / Gandy – Аплікатор-мікрогранулятор 12 В є еталоном надійності та технологічності у сучасному овочівництві. Завдяки продуманій кінематиці робочих органів, адаптивному регулюванню глибини та делікатним сепараційним елементам, машина забезпечує збереження структури ґрунту та товарного вигляду врожаю. Агрегатується з популярними класами тракторів, відрізняється низькою енергоємністю та простотою щоденного обслуговування. AGRO RENTEX надає повний комплекс супроводу: налаштування робочих органів під ваші ґрунти, постачання витратних матеріалів, виїзний сервіс та вигідні умови оренди/лізингу. Мікрогранулятор Zibo Gandy призначений для точного внесення малих доз інсектицидів, таких як «Регент», «Форс» та інші. Агрегатується з усіма видами картоплесаджалок, сівалок і машин для висаджування розсади, а також легко монтується на ґрунтообробну техніку. Основні характеристики : Бункер-накопичувач : обсяг 30 літрів.",
