    "shortDescription": "Спеціалізована польова техніка Struik LKB-SHIFT 1500 подрібнювач бадилля. Створена для бездоганної підготовки ґрунту, гребнеутворення, точної посадки та високопродуктивного збирання овочів без втрат.",
    "fullDescription": "Польовий агрегат Struik LKB-SHIFT 1500 подрібнювач бадилля є еталоном надійності та технологічності у сучасному овочівництві. Завдяки продуманій кінематиці робочих органів, адаптивному регулюванню глибини та делікатним сепараційним елементам, машина забезпечує збереження структури ґрунту та товарного вигляду врожаю. Агрегатується з популярними класами тракторів, відрізняється низькою енергоємністю та простотою щоденного обслуговування. AGRO RENTEX надає повний комплекс супроводу: налаштування робочих органів під ваші ґрунти, постачання витратних матеріалів, виїзний сервіс та вигідні умови оренди/лізингу. LKB-Shift 1500 – це ідеальний подрібнювач бадилля для використання в передній навішуванні під час збирання врожаю комбайном з боковою жниваркою. Таким чином, за один прохід можна прибирати бадилля і збирати крохмальні та інші сорти картоплі, значно збільшуючи продуктивність та заощаджуючи робочу силу. За допомогою гідравлічного бічного зміщення ботвоудалювача можна перемістити на 1,70 м вправо.",
