    "shortDescription": "Спеціалізована польова техніка Struik WEED-MASTER машина для механічного видалення бур'янів. Створена для бездоганної підготовки ґрунту, гребнеутворення, точної посадки та високопродуктивного збирання овочів без втрат.",
    "fullDescription": "Польовий агрегат Struik WEED-MASTER машина для механічного видалення бур'янів є еталоном надійності та технологічності у сучасному овочівництві. Завдяки продуманій кінематиці робочих органів, адаптивному регулюванню глибини та делікатним сепараційним елементам, машина забезпечує збереження структури ґрунту та товарного вигляду врожаю. Агрегатується з популярними класами тракторів, відрізняється низькою енергоємністю та простотою щоденного обслуговування. AGRO RENTEX надає повний комплекс супроводу: налаштування робочих органів під ваші ґрунти, постачання витратних матеріалів, виїзний сервіс та вигідні умови оренди/лізингу. Машина Weed-Master спеціально розроблена для механічного видалення бур'янів при вирощуванні таких культур як цибуля, буряк, часник, броколі, цвітна капуста, брюссельська капуста і багато інших культур, що висаджуються в рядах або на грядках. Частини рами оснащені спеціальною паралелограмною підвіскою, тому за будь-яких обставин машина ідеально йде за рівнем землі. Запатентовані зубці, що обертаються, працюють дуже близько до рослини або культури і виривають бур'яни разом з корінням.",
