    "shortDescription": "Спеціалізована польова техніка Struik VARIX 3000-OT роторний культиватор. Створена для бездоганної підготовки ґрунту, гребнеутворення, точної посадки та високопродуктивного збирання овочів без втрат.",
    "fullDescription": "Польовий агрегат Struik VARIX 3000-OT роторний культиватор є еталоном надійності та технологічності у сучасному овочівництві. Завдяки продуманій кінематиці робочих органів, адаптивному регулюванню глибини та делікатним сепараційним елементам, машина забезпечує збереження структури ґрунту та товарного вигляду врожаю. Агрегатується з популярними класами тракторів, відрізняється низькою енергоємністю та простотою щоденного обслуговування. AGRO RENTEX надає повний комплекс супроводу: налаштування робочих органів під ваші ґрунти, постачання витратних матеріалів, виїзний сервіс та вигідні умови оренди/лізингу. Ротор культиватора Struik VariX 3000-OT обертається проти напрямку руху. Ротор піднімає ґрунт угору і відкидає його до задньої частини машини на зубчасту рейку із пружинної сталі. Грудки та рослинні залишки падають прямо на нижню частину шару закладення насіння і покриваються шаром дрібного ґрунту.",
    "aliases": [
      "varix-3000-ot-rotornyj-kultyvator"
    ]
