    "fullDescription": "Польовий агрегат Struik VARIX TWIN ROTOR роторний культиватор з двома валами є еталоном надійності та технологічності у сучасному овочівництві. Завдяки продуманій кінематиці робочих органів, адаптивному регулюванню глибини та делікатним сепараційним елементам, машина забезпечує збереження структури ґрунту та товарного вигляду врожаю. Агрегатується з популярними класами тракторів, відрізняється низькою енергоємністю та простотою щоденного обслуговування. AGRO RENTEX надає повний комплекс супроводу: налаштування робочих органів під ваші ґрунти, постачання витратних матеріалів, виїзний сервіс та вигідні умови оренди/лізингу. Struik VariX Twinrotor – це унікальний роторний культиватор з двома валами ротора, кожен з яких працює на різній глибині. Основний ротор обробляє ґрунт на максимальну глибину 25 см і створює досить пухкий ґрунт для формування грядок або гребенів. Спочатку гребнеутворювач формує гребінь, а за ним другий ротор обробляє верхній шар гребеня зі змінною глибиною обробки від 0,5 до 5 см.",
