    "shortDescription": "Спеціалізована польова техніка Struik RF універсальний роторний культиватор. Створена для бездоганної підготовки ґрунту, гребнеутворення, точної посадки та високопродуктивного збирання овочів без втрат.",
    "fullDescription": "Польовий агрегат Struik RF універсальний роторний культиватор є еталоном надійності та технологічності у сучасному овочівництві. Завдяки продуманій кінематиці робочих органів, адаптивному регулюванню глибини та делікатним сепараційним елементам, машина забезпечує збереження структури ґрунту та товарного вигляду врожаю. Агрегатується з популярними класами тракторів, відрізняється низькою енергоємністю та простотою щоденного обслуговування. AGRO RENTEX надає повний комплекс супроводу: налаштування робочих органів під ваші ґрунти, постачання витратних матеріалів, виїзний сервіс та вигідні умови оренди/лізингу. Struik RF – це універсальний роторний культиватор для всіх видів обробки ґрунту будь-якого типу. Машина випускається з розмірами від 2х75 до 8х90 см. Верхній кожух виготовлений зі сталі, але може також виготовлятися з гуми.",
