    "fullDescription": "Польовий агрегат Struik VariX універсальний роторний культиватор є еталоном надійності та технологічності у сучасному овочівництві. Завдяки продуманій кінематиці робочих органів, адаптивному регулюванню глибини та делікатним сепараційним елементам, машина забезпечує збереження структури ґрунту та товарного вигляду врожаю. Агрегатується з популярними класами тракторів, відрізняється низькою енергоємністю та простотою щоденного обслуговування. AGRO RENTEX надає повний комплекс супроводу: налаштування робочих органів під ваші ґрунти, постачання витратних матеріалів, виїзний сервіс та вигідні умови оренди/лізингу. Серія культиваторів VariX є наступником серії RF. VariX – це універсальний роторний культиватор , який ідеально підходить для всіх видів обробки ґрунту будь-якого типу. Роторний культиватор VariX оснащений пружною верхньою кришкою.",
