    "shortDescription": "Спеціалізована польова техніка Підгортач-гребнеутворювач Zibo Super. Створена для бездоганної підготовки ґрунту, гребнеутворення, точної посадки та високопродуктивного збирання овочів без втрат.",
    "fullDescription": "Польовий агрегат Підгортач-гребнеутворювач Zibo Super є еталоном надійності та технологічності у сучасному овочівництві. Завдяки продуманій кінематиці робочих органів, адаптивному регулюванню глибини та делікатним сепараційним елементам, машина забезпечує збереження структури ґрунту та товарного вигляду врожаю. Агрегатується з популярними класами тракторів, відрізняється низькою енергоємністю та простотою щоденного обслуговування. AGRO RENTEX надає повний комплекс супроводу: налаштування робочих органів під ваші ґрунти, постачання витратних матеріалів, виїзний сервіс та вигідні умови оренди/лізингу. Загальна характеристика:- збільшує розмір гребеня, менше зелених бульб;- ущільнює гребені, затримує вологу і гребінь залишається незмінним протягом весь сезон;- універсальність використання у різні періоди часу;- можна використовувати до змикання бадилля, гребінь швидше нагрівається і картопля розвивається швидше;- гребінь краще зберігає форму навіть під час сильного дощу;- сповільнюється підвищення температури в гребені в спекотні літні періоди, що покращує якість зберігання картоплі;- бур'яни можуть бути видалені за одну обробку, таким чином досягається економія при розпиленні гербіцидів. Моделі Zibo Super:- 4-рядний підгортач, тип «ZIBO Super», вкл. 2 опорних колеса, глубокорозрихлювачі, рухливі пластини ПВХ і комплект обрізних плит- 8-рядний підгортач «ZIBO Super», з гідравлічним втягуванням, вкл.",
