    "fullDescription": "Запасна частина Grimme B94.04908 – Джойстик 2х позиційний призначена для планового сервісного обслуговування та ремонту вузлів сільськогосподарської техніки. Виготовлена з високоякісних легованих сплавів та посилених еластомерів, що гарантує стійкість до абразивного зносу, ударних навантажень та вібрацій під час роботи з важкими ґрунтами. Використання перевірених комплектуючих від AGRO RENTEX виключає ризик раптових простоїв техніки в полі, продовжує життєвий цикл сполучених вузлів та суттєво знижує експлуатаційні витрати господарства. Завжди в наявності на нашому центральному складі в Рівному з можливістю експрес-доставки по Україні. Двохходовий джойстик керування картоплезбиральних комбайныв GRIMME Оригінальний елемент керування для пультів ккомбайнів GRIMME. Забезпечує точне та плавне керування функціями машини, відрізняється високою надійністю та стійкістю до інтенсивної експлуатації в польових умовах. Оригінальний номер деталі: B94."
